mapper.update:
update cross_border_account
set balance  = balance - #{amount},
    update_time = now()
where id = #{id}
  and balance - frozen_balance >= #{amount}

update cross_border_account
set frozen_balance = frozen_balance + #{amount},
    update_time = now()
where id = #{id}
  and balance - frozen_balance >= #{amount}

update cross_border_account
set frozen_balance = frozen_balance - #{amount},
    update_time = now()
where id = #{id}
  and frozen_balance >= #{amount}

update cross_border_account
set status      = #{status},
    update_time = now()
where id = #{id}
  and status = #{expectedStatus}
